package candidate

import (
	"context"
	"encoding/json"
	"errors"
	"strings"

	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/ledger"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

const opReassign = "bulk-reassign.v6"

func newReassign(pool *pgxpool.Pool) protocol.AssignHandler {
	return func(ctx context.Context, u app.Identity, key string, ids []string, assignee string) (protocol.AssignResult, bool, error) {
		for _, id := range ids {
			if strings.ContainsRune(id, 0) {
				return protocol.AssignResult{}, false, &protocol.Rejection{Status: 404}
			}
		}
		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		defer tx.Rollback(ctx)
		if _, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role); err != nil {
			return protocol.AssignResult{}, false, err
		}
		lock, _ := json.Marshal([]string{opReassign, u.Tenant, u.User, key})
		if _, err = tx.Exec(ctx, `SELECT pg_advisory_xact_lock(hashtextextended($1,0))`, string(lock)); err != nil {
			return protocol.AssignResult{}, false, err
		}
		hash := ledger.Fingerprint(opReassign+"\n"+assignee, ids)
		var savedHash string
		var saved []byte
		err = tx.QueryRow(ctx, `SELECT "requestHash",response FROM "ActionRequest" WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`,
			u.Tenant, u.User, opReassign, key).Scan(&savedHash, &saved)
		switch {
		case err == nil && savedHash != hash:
			return protocol.AssignResult{}, false, &protocol.Rejection{Status: 409}
		case err == nil:
			// The saved response is in the format {"reassignedIds":[...],"assignee":"..."}
			var rawResponse map[string]json.RawMessage
			if err = json.Unmarshal(saved, &rawResponse); err != nil {
				return protocol.AssignResult{}, false, err
			}

			// Extract IDs and assignee from the saved response
			var savedIds []string
			var assigneeVal string
			for key, val := range rawResponse {
				if key == "assignee" {
					if err = json.Unmarshal(val, &assigneeVal); err != nil {
						return protocol.AssignResult{}, false, err
					}
				} else {
					if err = json.Unmarshal(val, &savedIds); err != nil {
						return protocol.AssignResult{}, false, err
					}
				}
			}
			return protocol.AssignResult{Field: "reassignedIds", IDs: savedIds, Assignee: assigneeVal}, true, tx.Commit(ctx)
		case !errors.Is(err, pgx.ErrNoRows):
			return protocol.AssignResult{}, false, err
		}
		// Verify assignee is an active approver in the current tenant
		var assigneeExists bool
		err = tx.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM "TenantMember" WHERE "tenantId"=$1 AND "userId"=$2 AND role='approver' AND active)`,
			u.Tenant, assignee).Scan(&assigneeExists)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		if !assigneeExists {
			return protocol.AssignResult{}, false, &protocol.Rejection{Status: 409}
		}
		// Update purchases: must be submitted, created by someone else, in current tenant
		rows, err := tx.Query(ctx, `UPDATE "Purchase" SET "assigneeId"=$1 WHERE id=ANY($2::text[]) AND "tenantId"=$3 AND "createdBy"<>$4 AND status='submitted' RETURNING id`, assignee, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		changed := 0
		for rows.Next() {
			changed++
		}
		rows.Close()
		if err = rows.Err(); err != nil {
			return protocol.AssignResult{}, false, err
		}
		// Ineligible targets (missing, other tenant, wrong owner or state) all get the same
		// 409; unlike the legacy per-purchase handlers in internal/app, Actions never reveal existence.
		if changed != len(ids) {
			return protocol.AssignResult{}, false, &protocol.Rejection{Status: 409}
		}
		batch := &pgx.Batch{}
		for _, id := range ids {
			batch.Queue(`INSERT INTO "AssignmentHistory" ("tenantId","purchaseId","toAssignee","changedBy",operation,"idempotencyKey") VALUES ($1,$2,$3,$4,$5,$6)`,
				u.Tenant, id, assignee, u.User, opReassign, key)
		}
		result := protocol.AssignResult{Field: "reassignedIds", IDs: ids, Assignee: assignee}
		response, err := json.Marshal(result)
		if err != nil {
			return protocol.AssignResult{}, false, err
		}
		batch.Queue(`INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response) VALUES ($1,$2,$3,$4,$5,$6::jsonb)`,
			u.Tenant, u.User, opReassign, key, hash, string(response))
		if err = tx.SendBatch(ctx, batch).Close(); err != nil {
			return protocol.AssignResult{}, false, err
		}
		if err = tx.Commit(ctx); err != nil {
			return protocol.AssignResult{}, false, err
		}
		return result, false, nil
	}
}

